"""Dependency-light static Pages renderer. All source content is HTML escaped."""
import csv
import json
from html import escape as esc
from pathlib import Path
from model import fair_line

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT/'docs'

def e(value):
    return esc(str(value)) if value is not None else ''

def link(url, label='Official source'):
    return f'<a href="{e(url)}" rel="noopener noreferrer">{e(label)} ↗</a>'

def table(headers, rows, id_=''):
    return f'<div class="table-wrap"><table id="{id_}"><thead><tr>'+''.join(f'<th scope="col">{e(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def build():
    data = json.loads((OUT/'data/matches.json').read_text())
    quotes = json.loads((OUT/'data/quotes.json').read_text())
    health = json.loads((OUT/'data/health.json').read_text())
    matches = data['matches']
    visible = sum(m['visible_card'] for m in matches)
    nav = [('index.html','Overview'),('matches.html','Match directory'),('odds.html','External lines'),('methodology.html','Methodology'),('sources.html','Sources & audit'),('flags.html','Flagged for Review')]
    def page(file, title, intro, body):
        menu = ''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{t}</a>' for f,t in nav)
        html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Source-audited esports match directory and independent no-vig reference lines."><title>{e(title)} · LineWatch</title><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html"><span class="brand-icon">≋</span> LINEWATCH <small>ESPORTS RESEARCH</small></a><span class="mode">● Evidence-first / not a live odds feed</span></header><div class="layout"><aside><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">{menu}</nav><div class="sidebar-note">Independent research<br>Not affiliated with Hotspawn<br><br>No crowd-pick inputs.<br>No invented prices.</div></aside><main id="main"><div class="eyebrow">HOTSPAWN PICK’EM · SOURCE AUDIT</div><h1>{e(title)}</h1><p class="intro">{intro}</p>{body}<footer>Fixture retrieval: {e(data['observed_at'])} · Source cache Age: {e(data.get('http_metadata',{}).get('Age'))} seconds.<br>Quotes are dated reference observations, not current executable prices. For research only; no guarantee of outcomes.</footer></main></div></body></html>'''
        (OUT/file).write_text(html)
    cards = ''.join(f'<section class="metric"><span>{label}</span><strong>{value}</strong><small>{detail}</small></section>' for label,value,detail in [('Embedded fixtures',len(matches),'All records in this source response'),('Visible lobby cards',visible,'A subset of the embedded records'),('Current probabilities',0,'No fully verified current markets'),('Reference markets',len(quotes),'External quotes; not linked as current')])
    alert = '<div class="notice"><strong>Coverage is not the same as verification.</strong> All embedded fixtures are listed. Current odds and probabilities remain blank until event identity, market, and freshness are verified. <a href="flags.html">See open findings →</a></div>'
    page('index.html','A clearer view of the lines.','One place to inspect the match list, trace the evidence, and see exactly what remains unverified.',cards.join(['<div class="metrics">','</div>'])+alert+'''<div class="section-head"><h2>Research workspace</h2><span>Transparent by design</span></div><div class="tiles"><a class="tile" href="matches.html"><span>01 / DIRECTORY</span><h2>Every captured fixture →</h2><p>Search teams and tournaments. Separate visible cards from historical embedded records.</p></a><a class="tile" href="odds.html"><span>02 / ANALYSIS</span><h2>Independent fair lines →</h2><p>Inspect the bookmaker inputs and our proportional no-vig calculation, with limitations attached.</p></a><a class="tile" href="flags.html"><span>03 / VERIFICATION</span><h2>Open findings →</h2><p>Missing prices, conflicting schedules, stale records, and source-access limitations.</p></a></div><h2>What the audit found</h2>'''+table(['Finding','Evidence'],[['The public page contains Angular transfer-state with fixture IDs, names, sport, epoch timestamps and permalinks.',link(data['source'])],['Pick percentages are crowd selections, not betting probabilities. They are excluded from the normalized dataset.',link(data['source'])],['Two explicit Match Winner markets were observed on an external bookmaker. They are reference observations only.',link(quotes[0]['source'],'Thunderpick market')]]) )
    rows=[]
    for m in sorted(matches,key=lambda x:x['start_utc'] or ''):
        rows.append([f'<strong>{e(m["team_a"])} <span class="vs">vs</span> {e(m["team_b"])}</strong><small>#{e(m["id"])} · {e(m["game"])}</small>',e(m['tournament']),e(m['start_utc']), 'Visible card' if m['visible_card'] else 'Embedded only', '', '', '<span class="pill">Unverified odds</span>',link(m['source'],'Fixture source')])
    controls='''<div class="controls"><label>Search fixtures<input id="search" type="search" placeholder="Team, tournament, ID…"></label><label>Source visibility<select id="visibility"><option value="">All embedded fixtures</option><option value="Visible card">Visible cards only</option><option value="Embedded only">Embedded only</option></select></label><a class="button" href="data/matches.csv" download>Download CSV ↓</a></div><p id="row-count" aria-live="polite"></p>'''
    page('matches.html','Match directory','UTC start times are converted from explicit source epoch milliseconds, not inferred from display text. Blank price and probability cells mean unverified. “Scheduled” source records can be historical.',alert+controls+table(['Match / game','Tournament','Source start (UTC)','Visibility','Odds A / B','Probability A / B','Verification','Evidence'],rows,'matches')+'<p>Fixture facts are source-observed, not independently organizer-confirmed. The source response does not establish complete coverage across games. <a href="data/matches.json">Full JSON, IDs and per-row flags</a>.</p>')
    oddsrows=[]
    for q in quotes:
        calc=fair_line(q['american_a'],q['american_b'])
        oddsrows.append([f'<strong>{e(q["team_a"])} / {e(q["team_b"])}</strong><small>{e(q["market"])} · {e(q["format"])}</small>',f'{q["american_a"]:+d} / {q["american_b"]:+d}',f'{calc["probability_a"]:.2%} / {calc["probability_b"]:.2%}',f'{calc["fair_a"]:.3f} / {calc["fair_b"]:.3f}',f'{calc["overround"]:.2%}',e(q['observed_date']),e(q['flag']),link(q['source'],'Bookmaker market')])
    page('odds.html','External lines','Our calculated, margin-removed reference lines. These are not Hotspawn percentages, current picks, or an independently trained predictive model. A / B follows the displayed team order.', '<div class="notice"><strong>Reference only — freshness unverified.</strong> Provider quote timestamps were absent. No reference market is promoted into the current match table. The retrieval service may return cached content.</div>'+table(['Market / A vs B','American A / B','Calculated probability A / B','Our fair decimal A / B','Overround','Observed date','Limitations','Evidence'],oddsrows)+'<h2>How to interpret this</h2><p>The probabilities are calculations from the displayed external prices, not verified real-world win probabilities. Each pair uses one bookmaker and one two-outcome Match Winner market. There is no cross-book consensus, backtest, or calibration claim.</p><p><a href="evidence/odds-extract.txt">Review source excerpts</a> · <a href="data/quotes.json">Download quote inputs</a> · <a href="methodology.html">Read the calculation</a></p>')
    page('methodology.html','Methodology','Explicit inputs. Reproducible arithmetic. Missing evidence stays missing.', '''<article><h2>01 / Discover, do not guess</h2><p>Read the official public lobby HTML, then its <code>script#ng-state</code> transfer-state. Locate the response whose URL ends in <code>/api/v1/fixtures</code>; keys are discovered rather than hard-coded. Read the embedded permalink map without calling its admin-named endpoint. Preserve fixture IDs and source epoch timestamps. Inspect rendered cards separately from embedded records.</p><h2>02 / Verify a market before joining it</h2><p>A valid current join needs both participant identities, competition, UTC start, series format, full Match Winner market, outcome coverage, quote timestamp and source URL. Similar team names or dates alone do not qualify. There are currently no validated joins. No authentication or anti-bot bypass is attempted.</p><h2>03 / Originate a reference line</h2><p>For American odds a ≥ +100: decimal d = 1 + a/100. For a ≤ −100: d = 1 + 100/|a|. For each outcome q = 1/d. Overround = qA + qB − 1. Our proportional no-vig estimate pA = qA/(qA + qB), pB = qB/(qA + qB). Our fair decimal lines are 1/pA and 1/pB.</p><p>This is a disclosed modeling choice, not a sourced fact or a claim of true probability. Do not apply a two-outcome calculation to a three-way market, map handicap, partial market, or mixed live/pre-match quotes.</p><p>Odds-conversion formulas were also checked against the <a href="https://help.smarkets.com/hc/en-gb/articles/214058369-How-to-calculate-implied-probability-in-betting">official Smarkets help article</a>. Proportional margin removal remains our modeling choice.</p><h2>04 / Refresh without misrepresenting freshness</h2><p>GitHub Actions attempts public-source collection hourly. The collector retains the previous snapshot on failures and publishes a source-health report. HTTP Date, cache Age, retrieval time and snapshot hash remain visible. A new build is not a new odds observation. Reference quotes retain their original observed date; no automatic odds adapter is validated.</p><h2>05 / Limits</h2><p>We do not assign neutral 50/50 probabilities, extrapolate missing odds, interpret pick popularity as strength, or fit an unsupported statistical model. Historical scheduled records remain visible and flagged. A complete up-to-date priced list has not been achieved.</p></article>''')
    source_rows=[[link(data['source'],'Hotspawn lobby'),'Primary for its own fixture inventory',f'{len(matches)} embedded records; {visible} rendered cards. Cached source, not independently confirmed.'],[link('https://play.hotspawn.com/how-it-works','Hotspawn rules'),'Primary for published game rules','Help page states 5-minute lock; fixture payload contains 360-second offsets.'],[link('https://www.hltv.org/betting/analytics','HLTV analytics'),'Secondary esports research','Retrieved excerpt had blank best-odds fields and unrelated/future event content; not used as price evidence.'],[link('https://thunderpick.io/esports/cs2-betting','Thunderpick'),'Primary bookmaker','Hosted runner received HTTP 403 challenge. Two market-specific fetch_page extracts are preserved separately.']]
    source_rows.extend([[link(q['source'],q['team_a']+' / '+q['team_b']),'Primary bookmaker market','Match Winner prices observed 2026-10-13; provider quote time and current status unverified.'] for q in quotes])
    healthrows=[[link(s['url']), e(s['status']),e(s.get('error'))] for s in health['sources']]
    page('sources.html','Sources & audit','Evidence is scoped to what a source actually establishes. An official Hotspawn link verifies what Hotspawn listed, not an external win probability.',table(['Source','Authority / scope','Review result'],source_rows)+'<h2>Latest automated attempt</h2><p>'+e(health['attempted_at'])+'</p>'+table(['Source','Collection status','Error'],healthrows)+'<h2>Independent audit handoffs</h2><p><a href="evidence/audit-1d4de836.json">Independent 86-row source comparison</a> · <a href="evidence/audit-1916f96c.md">Independent sportsbook and lobby report</a></p><h2>Reproduce the audit</h2><p><a href="evidence/latest-lobby.txt">Preserved public HTML</a> · <a href="evidence/lobby-extract.txt">Earlier text snapshot (26 cards)</a> · <a href="evidence/odds-extract.txt">Quote excerpts</a> · <a href="data/health.json">Health JSON</a></p><p>Latest normalized source SHA-256: <code>'+e(data['sha256'])+'</code>. The text snapshot and later hosted-runner response are different observations; they are not merged as simultaneous evidence.</p><p>The starting repository contained only a one-line README, with no existing data or application to verify.</p>')
    findings=[['F01','No current external probabilities','Every fixture lacks a fully validated current external market. All current odds and probability fields are blank.',data['source']],['F02','Completeness unresolved',f'The earlier text snapshot showed 26 cards, 60 weekly matches and 86 filter entries. The later public HTML contains {len(matches)} fixtures and {visible} rendered cards. These represent different scopes/times, not a verified global total.',data['source']],['F03','Cached source','Hosted-runner response reported cache Age 3839 seconds. Displayed data can lag retrieval time.',data['source']],['F04','Conflicting lock rules','Help page says picks lock 5 minutes before start; embedded fixture lock_offset_sec values include 360 seconds. Do not assume the help rule matches the payload.','https://play.hotspawn.com/how-it-works'],['F05','Bookmaker access blocked','Hosted-runner request received HTTP 403 / Cloudflare challenge. No bypass attempted; automatic odds ingestion remains incomplete.','https://thunderpick.io/esports/cs2-betting'],['F06','Timezone display differs','Astralis–Sashi match page shows 10:00, lobby extraction 06:00. Use explicit epoch conversion for source UTC; bookmaker timezone not verified.','https://www.hotspawn.com/matches/astralis-vs-sashi-stake-pulse-beat-iii-1079438']]
    for i,q in enumerate(quotes,7):
        findings.append([f'F{i:02}',q['team_a']+' / '+q['team_b'],q['flag'],q['source']])
    findings.extend([
        ['F09','Historical scheduled records','Independent pinned-snapshot audit: 60 of 86 start timestamps precede the HTTP response date. All 86 source statuses say scheduled, and all formats are null. This is not proof of completed matches.',data['source']],
        ['F10','LoL coverage unverified','All 86 captured fixtures are CS2, though tenant configuration enables CS2 and LOL. No complete LoL inventory is verified.',data['source']],
        ['F11','GG.BET regional response','Official response rejects visitors from the retrieval region; not a claim of universal unavailability. No bypass attempted.','https://gg.bet/en/esports'],
        ['F12','Rivalry closure notice','Official page states operations have ceased and player access is unavailable; not used as an odds source.','https://www.rivalry.com/operationally-closed'],
        ['F13','9z identity follow-up','Official Hotspawn detail explicitly links 9z Team under the 9z heading. This resolves the label relation, but not bookmaker event/timezone/freshness verification.','https://www.hotspawn.com/matches/9z-vs-aurora-thunderpick-world-championship-2026-1080176']
    ])
    flagrows=[[e(i),e(title),e(detail),'<span class="pill">Needs review</span>',link(url)] for i,title,detail,url in findings]
    perrows=[[e(m['id']),e(m['team_a']+' / '+m['team_b']),e('; '.join(m['flags'])),link(m['source'])] for m in matches]
    page('flags.html','Flagged for Review','Published limitations do not block the site. They do block unsupported claims of verification, freshness, or complete priced coverage.',table(['ID','Finding','Detail','Status','Official source'],flagrows)+'<h2>Row-by-row verification gaps</h2>'+table(['Fixture ID','Match','Missing / irregular evidence','Official source'],perrows))
    with (OUT/'data/matches.csv').open('w',newline='') as f:
        fields=['id','team_a','team_b','game','tournament','start_utc','source_status','visible_card','odds_a','odds_b','probability_a','probability_b','source','status']
        writer=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');writer.writeheader();writer.writerows(matches)
    (OUT/'.nojekyll').touch()

if __name__=='__main__':
    build()
